<template>
  <main class="alchemy-stage" :class="`variant-${variant}`" :style="cssVars" @click="skipToFinal">
    <div class="room-props" aria-hidden="true"><i class="cabinet"/><i class="gourd"/><i class="mortar"/></div><div class="vignette"/>
    <header><span>岐黄</span><p>小岐的丹房 · 生成中</p></header><button class="skip" type="button" @click.stop="skipToFinal">{{ finalizing ? '收丹中' : '跳至终态' }}</button>
    <section class="stage-main"><div class="background-title">{{ currentStep.label }}</div><AlchemyStepRail :steps="steps" :current-index="safeIndex" :state-copy="stateCopy" :completed-indices="completedIndices"/><div class="furnace-zone"><AlchemyFurnace ref="furnace" :config="config" :heat="heat" :offline="status === 'offline'" :failed="status === 'failed'"/></div><AlchemyMascot :heat="heat" :step-id="currentStep.id" :offline="status === 'offline'" :failed="status === 'failed'" :celebrating="celebrating" :motion="config.mascotMotion" :frequency="config.bubbleFrequency"/><Transition name="card"><article v-if="showCard" class="resource-card"><p>小岐炼成的资源</p><h3>《清热药 · 药证辨析》</h3><span>12 个溯源考点 · 已收入卷册</span></article></Transition></section>
  </main>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import AlchemyFurnace from './AlchemyFurnace.vue'
import AlchemyMascot from './AlchemyMascot.vue'
import AlchemyStepRail, { type AlchemyStep } from './AlchemyStepRail.vue'
import { resolveAlchemyStepLabels } from './alchemyStepLabels'
import { alchemyVariants, heatForStep, type AlchemyVariant, type AlchemyVisualConfig } from '../../config/alchemy-stage'
export type AlchemyStreamEvent = { type: 'step'; stepId: string; label?: string } | { type: 'step_done'; stepId: string } | { type: 'status'; status: 'offline' | 'failed' | 'reconnected' } | { type: 'complete' }
const props = withDefaults(defineProps<{ events: readonly AlchemyStreamEvent[]; variant?: AlchemyVariant; config?: AlchemyVisualConfig }>(), { variant: 'night' })
const steps: AlchemyStep[] = [{ id: 'source', label: '翻检《本草》原文…', short: '本草' }, { id: 'relation', label: '梳理药证关联…', short: '药证' }, { id: 'distill', label: '淬炼考点…', short: '考点' }, { id: 'verify', label: '校验溯源…', short: '溯源' }, { id: 'compose', label: '排版成卷…', short: '成卷' }]
const furnace = ref<InstanceType<typeof AlchemyFurnace>>(); const currentIndex = ref(0); const completedIndices = ref<number[]>([]); const status = ref<'running' | 'offline' | 'failed'>('running'); const showCard = ref(false); const finalizing = ref(false); const celebrating = ref(false)
const config = computed(() => props.config ?? alchemyVariants[props.variant]); const heat = computed(() => heatForStep(currentIndex.value)); const safeIndex = computed(() => Math.min(currentIndex.value, steps.length - 1)); const currentStep = computed(() => steps[safeIndex.value]); const stateCopy = computed(() => status.value === 'offline' ? '炉火渐弱，小岐正在续薪' : status.value === 'failed' ? '这炉先歇歇，重新开炉' : '小岐守着火候，慢慢成卷')
const cssVars = computed(() => Object.fromEntries(Object.entries(config.value.palette).map(([key, value]) => [`--alchemy-${key.replace(/[A-Z]/g, char => `-${char.toLowerCase()}`)}`, value])))
const finish = async () => { if (finalizing.value || showCard.value) return; finalizing.value = true; celebrating.value = true; await furnace.value?.releaseElixir(); showCard.value = true; finalizing.value = false; window.setTimeout(() => celebrating.value = false, 1200) }
watch(() => props.events, events => { const latest = events[events.length - 1]; if (!latest) return; if (latest.type === 'step') { const index = steps.findIndex(step => step.id === latest.stepId); if (index >= 0) { currentIndex.value = index; status.value = 'running'; showCard.value = false } } else if (latest.type === 'step_done') { const index = steps.findIndex(step => step.id === latest.stepId); if (index >= 0 && !completedIndices.value.includes(index)) completedIndices.value = [...completedIndices.value, index] } else if (latest.type === 'status') { status.value = latest.status === 'reconnected' ? 'running' : latest.status; if (status.value === 'failed') showCard.value = false } else { completedIndices.value = steps.map((_, index) => index); currentIndex.value = steps.length; void finish() } }, { deep: true, immediate: true })
watch(() => props.events, events => { resolveAlchemyStepLabels(steps, events).forEach((step, index) => { steps[index].label = step.label }) }, { deep: true, immediate: true })
const skipToFinal = () => { if (status.value !== 'failed') { currentIndex.value = steps.length; void finish() } }; defineExpose({ skipToFinal })
</script>
