sition:absolute;z-index:6;bottom:38px;left:50%;width:min(350px,76vw);padding:17px 21px;border:1px solid var(--alchemy-gold);border-radius:5px;background:color-mix(in srgb,var(--alchemy-panel) 92%,transparent);box-shadow:inset 0 0 0 4px color-mix(in srgb,var(--alchemy-gold) 10%,transparent),0 14px 28px rgba(0,0,0,.25);transform:translateX(-50%)}.resource-card p,.resource-card span{margin:0;color:var(--alchemy-muted);font-size:11px;letter-spacing:1px}.resource-card h3{margin:7px 0;color:var(--alchemy-ink);font-size:18px}.card-enter-active{transition:opacity .38s,transform .38s}.card-enter-from{opacity:0;transform:translate(-50%,36px)}@media(max-width:850px){.alchemy-stage,.stage-main{min-height:790px}.background-title{top:180px;font-size:34px}.resource-card{bottom:22px}.room-props{opacity:.035}.stage-main{padding-top:95px}}
</style>
